select case when ss.revenue >= 3400 then 'high' when ss.revenue >= 500 then 'mid' else 'low' end revenue_bucket, count(*) row_count from inventory i left outer join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where month(i.last_restock) in (5, 7, 8) group by case when ss.revenue >= 3400 then 'high' when ss.revenue >= 500 then 'mid' else 'low' end order by row_count desc, revenue_bucket desc
